cls(4,'08:00','09:35','思想道德与法治 · 第1–2节','截图：第4–14周');cls(5,'08:00','09:35','高等数学(A) · 第1–2节','截图：第4–18周');cls(5,'09:55','11:30','丝绸文化与科技 · 第3–4节','截图：第5–12周');cls(5,'14:00','15:35','军事理论 / 创新方法基础 · 第5–6节','第5–8周军事理论；第10–17周创新方法基础');cls(5,'15:55','17:30','大学英语读写 · 第7–8节','截图：第4–19周');cls(5,'19:00','20:35','无机及分析化学 · 第9–10节','截图：第5–17周；与合唱/晚自习冲突，须确认学校要求');
cls(6,'08:00','09:35','计算思维与人工智能导论 · 第1–2节','截图：第4–16周');cls(6,'09:55','11:30','无机及分析化学 · 第3–4节','截图：第5–17周');cls(6,'14:00','15:35','高等数学(A) · 第5–6节','截图：第4–18周');
